            if not hasattr(e, '_scope'):
                e._finalize(scope)
            raise
    return scope[glom](target, spec, scope)


def register_op(op_name, **kwargs):
    _DEFAULT_SCOPE[TargetRegistry].register_op(op_name, **kwargs)
    return


def from_text(cls, text):
    return Path.from_text(text)


def items(self):
    return self.path_t.__ops__[1:]


def __getitem__(self, i):
    return self.path_t.__ops__[1:][i]


def register_op(self, op_name, auto_func=None, exact=False):
    self._op_auto_map[op_name] = auto_func
    self._op_type_map[op_name] = OrderedDict()
    self._op_type_tree[op_name] = OrderedDict()
    if not exact:
        for t in self._op_type_map[op_name]:
            self._register_fuzzy_type(op_name, t)
    return
